def parse_nested_parens(paren_string: str) -> str:
    def max_depth(s: str) -> int:
        # Track current depth and max depth without loops or recursion by using reduce
        from functools import reduce
        def update(acc, ch):
            current, maximum = acc
            if ch == '(':
                current += 1
                maximum = max(maximum, current)
            elif ch == ')':
                current -= 1
            return (current, maximum)
        _, maximum = reduce(update, s, (0, 0))
        return maximum

    groups = paren_string.split()
    depths = map(lambda s: str(max_depth(s)), groups)
    return ', '.join(depths)
