def find_solution(a, b, n):
    def extended_gcd(x, y):
        if y == 0:
            return (x, 1, 0)
        gcd, x1, y1 = extended_gcd(y, x % y)
        return (gcd, y1, x1 - (x // y) * y1)

    gcd, x0, y0 = extended_gcd(a, b)
    if n % gcd != 0:
        return None  # no integer solution

    factor = n // gcd
    x = x0 * factor
    y = y0 * factor

    # Adjust the solution to minimize |x|
    # General solution form: x = x + k*(b/gcd), y = y - k*(a/gcd)
    # Find k to bring x closer to zero
    b_div = b // gcd
    a_div = a // gcd
    k = round(-x / b_div)
    x += k * b_div
    y -= k * a_div

    return ('x = ', x, ', y = ', y)
```

