def get_total_number_of_sequences(n, m):
    # dp[i][x]: number of sequences of length i ending with x
    dp = [ [0]*(m+1) for _ in range(n+1) ]
    for x in range(1, m+1):
        dp[1][x] = 1
    for i in range(2, n+1):
        for x in range(1, m+1):
            prev_min = (x + 1) // 2  # smallest prev element so that x >= 2*prev
            s = 0
            # sum dp[i-1][p] for p <= prev_min
            # But since p must satisfy x >= 2*p, so p <= x//2
            max_prev = x // 2
            if max_prev >= 1:
                s = sum(dp[i-1][1:max_prev+1])
            dp[i][x] = s
    return sum(dp[n][1:m+1])
