def next_smallest_palindrome(n: int) -> int:
    s = str(n)
    length = len(s)
    half = (length + 1) // 2  # middle index for odd length, right half for even length

    left = s[:half]
    if length % 2 == 0:
        pal = left + left[::-1]
    else:
        pal = left + left[-2::-1]

    if int(pal) > n:
        return int(pal)

    # Increment the left half and form palindrome again
    left_num = int(left) + 1
    left = str(left_num)

    # Handle overflow when incrementing left half increases length
    if len(left) > half:
        # For example, 999 -> 1000, so palindrome length increases by 1 or 2
        if length % 2 == 0:
            # even length palindrome overflow, for example 9999 -> 10001
            return int("1" + ("0" * (length - 1)) + "1")
        else:
            # odd length palindrome overflow, for example 999 -> 1001
            return int("1" + ("0" * (length - 1)) + "1")

    if length % 2 == 0:
        pal = left + left[::-1]
    else:
        pal = left + left[-2::-1]

    return int(pal)
