def find_solution(a, b, n):
    y = 0
    while True:
        if (n - b * y) % a == 0:
            x = (n - b * y) // a
            return ('x = ', x, ', y = ', y)
        y += 1
        # Also check negative y if needed, starting from 0 upwards in absolute value
        if y > abs(n)*abs(b)+1:
            break
    # If no non-negative y solution found, try negative y in increasing abs value order
    for y in range(1, abs(n)*abs(b)+2):
        if (n - b * (-y)) % a == 0:
            x = (n - b * (-y)) // a
            return ('x = ', x, ', y = ', -y)
    return 'No solution'
